<script setup lang="ts">
import type { AdvisorStudent } from '../../types/domain'
import PageHeader from '../../components/BasePageHeader.vue'
type Filters={keyword:string;path:string;goalStatus:string;reviewStatus:string;guidanceRequested:string;sort:string}
defineProps<{ students:AdvisorStudent[]; filters:Filters; total:number; page:number; totalPages:number; loading:boolean; error:string }>()
const emit=defineEmits<{ updateFilters:[filters:Filters]; apply:[]; reset:[]; page:[next:number]; detail:[id:string] }>()
const path=(value?:string)=>({graduate:'国内升学',employment:'就业发展',overseas:'出国留学'} as Record<string,string>)[value||'']||'待确定'
const status=(value?:string)=>({good:'状态良好',todo:'待完善',late:'长期未复盘',review:'申请指导'} as Record<string,string>)[value||'']||value||'待评估'
</script>
<template><PageHeader eyebrow="辅导工作" title="学生列表" description="按发展路径、目标、复盘和指导申请筛选学生。"/><section class="card data-list-card advisor-list-card"><form class="advisor-filters" @submit.prevent="emit('apply')"><label>关键词<input :value="filters.keyword" @input="emit('updateFilters',{...filters,keyword:($event.target as HTMLInputElement).value})" placeholder="姓名、班级或目标"></label><label>发展路径<select :value="filters.path" @change="emit('updateFilters',{...filters,path:($event.target as HTMLSelectElement).value})"><option value="">全部路径</option><option value="graduate">国内升学</option><option value="employment">就业发展</option><option value="overseas">出国留学</option></select></label><label>目标状态<select :value="filters.goalStatus" @change="emit('updateFilters',{...filters,goalStatus:($event.target as HTMLSelectElement).value})"><option value="">全部目标</option><option value="HAS_GOAL">已设主目标</option><option value="NO_GOAL">未设主目标</option></select></label><label>复盘状态<select :value="filters.reviewStatus" @change="emit('updateFilters',{...filters,reviewStatus:($event.target as HTMLSelectElement).value})"><option value="">全部复盘</option><option value="REVIEWED_THIS_MONTH">本月已复盘</option><option value="LONG_NO_REVIEW">长期未复盘</option></select></label><label>指导申请<select :value="filters.guidanceRequested" @change="emit('updateFilters',{...filters,guidanceRequested:($event.target as HTMLSelectElement).value})"><option value="">全部</option><option value="true">已申请指导</option><option value="false">未申请指导</option></select></label><label>排序<select :value="filters.sort" @change="emit('updateFilters',{...filters,sort:($event.target as HTMLSelectElement).value})"><option value="-createdAt">最近更新</option><option value="name">姓名</option><option value="-completeness">档案完整度</option><option value="-planRate">计划完成率</option><option value="-lastReview">最近复盘</option></select></label><div class="advisor-filter-actions"><button class="primary-btn compact-btn">应用筛选</button><button class="outline-btn" type="button" @click="emit('reset')">重置</button></div></form><div class="list-summary"><span>共 <b>{{total}}</b> 名学生</span><span>第 {{page}} / {{totalPages}} 页</span></div><p v-if="loading" class="empty">正在读取学生数据…</p><p v-else-if="error" class="empty error-state">{{error}}</p><div v-else class="advisor-student-table"><div class="advisor-student-columns"><span>学生</span><span>发展状态</span><span>进度</span><span>最近复盘</span><span>操作</span></div><article v-for="student in students" :key="student.id"><div><b>{{student.name}}</b><small>{{student.className||'未填写班级'}} · {{student.id}}</small></div><div><span>{{path(student.path)}}</span><small>{{student.primaryGoal||'尚未设定主目标'}}{{student.direction?` · ${student.direction}`:''}}</small></div><div><span>档案 {{student.completeness??0}}% · 计划 {{student.planRate??0}}%</span><small>{{student.assessed?'已完成测评':'未完成测评'}}</small></div><div><em class="neutral">{{status(student.status)}}</em><small>{{student.lastReview||'暂无复盘'}}</small></div><button class="outline-btn" @click="emit('detail',student.id)">详情与指导</button></article><p v-if="!students.length" class="empty">当前筛选条件下没有学生记录。</p></div><div v-if="totalPages>1" class="advisor-pagination"><button class="outline-btn" :disabled="page<=1" @click="emit('page',page-1)">上一页</button><span>{{page}} / {{totalPages}}</span><button class="outline-btn" :disabled="page>=totalPages" @click="emit('page',page+1)">下一页</button></div></section></template>
